-- Baseline schema for the meeting platform.
-- Conventions: UUID primary keys generated by the application, timestamptz for instants (stored UTC),
-- IANA time-zone names stored next to any local date/time, optimistic locking via "version".

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ---------------------------------------------------------------- identity
CREATE TABLE users (
    id              uuid PRIMARY KEY,
    email           varchar(320) NOT NULL,
    display_name    varchar(120) NOT NULL,
    time_zone       varchar(64)  NOT NULL DEFAULT 'UTC',
    avatar_url      varchar(1024),
    email_verified  boolean      NOT NULL DEFAULT false,
    system_role     varchar(32)  NOT NULL DEFAULT 'USER',
    status          varchar(32)  NOT NULL DEFAULT 'ACTIVE',
    created_at      timestamptz  NOT NULL,
    updated_at      timestamptz  NOT NULL,
    version         bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_users_system_role CHECK (system_role IN ('SYSTEM_ADMIN', 'USER')),
    CONSTRAINT ck_users_status CHECK (status IN ('ACTIVE', 'DISABLED'))
);
CREATE UNIQUE INDEX ux_users_email ON users (lower(email));

CREATE TABLE user_credentials (
    user_id              uuid PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    password_hash        varchar(255) NOT NULL,
    password_changed_at  timestamptz  NOT NULL,
    failed_attempts      integer      NOT NULL DEFAULT 0,
    locked_until         timestamptz
);

CREATE TABLE external_identity_links (
    id          uuid PRIMARY KEY,
    user_id     uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    provider    varchar(32)  NOT NULL,
    subject     varchar(255) NOT NULL,
    email       varchar(320),
    created_at  timestamptz  NOT NULL,
    CONSTRAINT ux_external_identity UNIQUE (provider, subject)
);
CREATE INDEX ix_external_identity_user ON external_identity_links (user_id);

CREATE TABLE user_sessions (
    id                   uuid PRIMARY KEY,
    user_id              uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    refresh_token_hash   varchar(64)  NOT NULL,
    previous_token_hash  varchar(64),
    client_type          varchar(16)  NOT NULL,
    user_agent           varchar(512),
    ip_address           varchar(64),
    created_at           timestamptz  NOT NULL,
    last_used_at         timestamptz  NOT NULL,
    expires_at           timestamptz  NOT NULL,
    revoked_at           timestamptz,
    revoke_reason        varchar(64)
);
CREATE UNIQUE INDEX ux_user_sessions_token ON user_sessions (refresh_token_hash);
CREATE INDEX ix_user_sessions_previous ON user_sessions (previous_token_hash);
CREATE INDEX ix_user_sessions_user ON user_sessions (user_id) WHERE revoked_at IS NULL;

CREATE TABLE verification_tokens (
    id          uuid PRIMARY KEY,
    user_id     uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    purpose     varchar(32) NOT NULL,
    token_hash  varchar(64) NOT NULL,
    expires_at  timestamptz NOT NULL,
    used_at     timestamptz,
    created_at  timestamptz NOT NULL,
    CONSTRAINT ck_verification_purpose CHECK (purpose IN ('EMAIL_VERIFICATION', 'PASSWORD_RESET'))
);
CREATE UNIQUE INDEX ux_verification_token_hash ON verification_tokens (token_hash);
CREATE INDEX ix_verification_user ON verification_tokens (user_id, purpose);

-- ---------------------------------------------------------------- roles & permissions (reference data)
CREATE TABLE roles (
    code         varchar(32) PRIMARY KEY,
    scope        varchar(16) NOT NULL,
    description  varchar(255) NOT NULL,
    CONSTRAINT ck_roles_scope CHECK (scope IN ('SYSTEM', 'ORGANIZATION', 'MEETING'))
);

CREATE TABLE permissions (
    code         varchar(64) PRIMARY KEY,
    description  varchar(255) NOT NULL
);

CREATE TABLE role_permissions (
    role_code        varchar(32) NOT NULL REFERENCES roles (code),
    permission_code  varchar(64) NOT NULL REFERENCES permissions (code),
    PRIMARY KEY (role_code, permission_code)
);

INSERT INTO roles (code, scope, description) VALUES
    ('SYSTEM_ADMIN',       'SYSTEM',       'Operates the whole platform'),
