    ('ORGANIZATION_ADMIN', 'RECORDING_VIEW'),
    ('ORGANIZATION_ADMIN', 'RECORDING_MANAGE'),
    ('HOST', 'MEETING_EDIT'), ('HOST', 'MEETING_END'), ('HOST', 'MEETING_MODERATE'), ('HOST', 'MEETING_ASSIGN_ROLES'),
    ('HOST', 'MEETING_RECORD'), ('HOST', 'MEETING_SCREEN_SHARE'), ('HOST', 'MEETING_CHAT'), ('HOST', 'MEETING_FILE_SHARE'),
    ('HOST', 'RECORDING_VIEW'), ('HOST', 'RECORDING_MANAGE'),
    ('CO_HOST', 'MEETING_MODERATE'), ('CO_HOST', 'MEETING_RECORD'), ('CO_HOST', 'MEETING_SCREEN_SHARE'),
    ('CO_HOST', 'MEETING_CHAT'), ('CO_HOST', 'MEETING_FILE_SHARE'), ('CO_HOST', 'RECORDING_VIEW'),
    ('PARTICIPANT', 'MEETING_CHAT'), ('PARTICIPANT', 'MEETING_FILE_SHARE'), ('PARTICIPANT', 'RECORDING_VIEW'),
    ('GUEST', 'MEETING_CHAT');

-- ---------------------------------------------------------------- organizations
CREATE TABLE organizations (
    id                               uuid PRIMARY KEY,
    name                             varchar(200) NOT NULL,
    slug                             varchar(80)  NOT NULL,
    default_recording_retention_days integer      NOT NULL DEFAULT 90,
    allow_guests                     boolean      NOT NULL DEFAULT true,
    created_at                       timestamptz  NOT NULL,
    updated_at                       timestamptz  NOT NULL,
    version                          bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ux_organizations_slug UNIQUE (slug),
    CONSTRAINT ck_org_retention CHECK (default_recording_retention_days BETWEEN 1 AND 3650)
);

CREATE TABLE organization_members (
    id               uuid PRIMARY KEY,
    organization_id  uuid        NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
    user_id          uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role             varchar(32) NOT NULL REFERENCES roles (code),
    joined_at        timestamptz NOT NULL,
    CONSTRAINT ux_org_member UNIQUE (organization_id, user_id),
    CONSTRAINT ck_org_member_role CHECK (role IN ('ORGANIZATION_ADMIN', 'MEMBER'))
);
CREATE INDEX ix_org_members_user ON organization_members (user_id);

-- ---------------------------------------------------------------- meetings
CREATE TABLE meetings (
    id                    uuid PRIMARY KEY,
    join_code             varchar(16)  NOT NULL,
    title                 varchar(200) NOT NULL,
    description           varchar(5000),
    type                  varchar(16)  NOT NULL,
    status                varchar(16)  NOT NULL,
    media_mode            varchar(16)  NOT NULL DEFAULT 'VIDEO',
    privacy               varchar(16)  NOT NULL DEFAULT 'LINK',
    organization_id       uuid REFERENCES organizations (id) ON DELETE SET NULL,
    host_id               uuid         NOT NULL REFERENCES users (id),
    start_time            timestamptz,
    end_time              timestamptz,
    time_zone             varchar(64)  NOT NULL,
    recurrence_rule       varchar(512),
    password_hash         varchar(255),
    waiting_room_enabled  boolean      NOT NULL DEFAULT false,
    allow_guests          boolean      NOT NULL DEFAULT true,
    join_before_host      boolean      NOT NULL DEFAULT true,
    mute_on_entry         boolean      NOT NULL DEFAULT false,
    max_participants      integer      NOT NULL DEFAULT 100,
    screen_share_policy   varchar(16)  NOT NULL DEFAULT 'EVERYONE',
    chat_enabled          boolean      NOT NULL DEFAULT true,
    locked                boolean      NOT NULL DEFAULT false,
    cancelled_at          timestamptz,
    cancel_reason         varchar(500),
    created_at            timestamptz  NOT NULL,
    updated_at            timestamptz  NOT NULL,
    version               bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ux_meetings_join_code UNIQUE (join_code),
    CONSTRAINT ck_meetings_type CHECK (type IN ('INSTANT', 'SCHEDULED', 'PERSONAL_ROOM', 'ONE_TO_ONE')),
    CONSTRAINT ck_meetings_status CHECK (status IN ('SCHEDULED', 'LIVE', 'ENDED', 'CANCELLED')),
    CONSTRAINT ck_meetings_media CHECK (media_mode IN ('VIDEO', 'AUDIO_ONLY')),
    CONSTRAINT ck_meetings_privacy CHECK (privacy IN ('LINK', 'ORGANIZATION', 'INVITEES_ONLY')),
    CONSTRAINT ck_meetings_share CHECK (screen_share_policy IN ('EVERYONE', 'HOSTS_ONLY')),
    CONSTRAINT ck_meetings_capacity CHECK (max_participants BETWEEN 2 AND 300),
    CONSTRAINT ck_meetings_window CHECK (end_time IS NULL OR start_time IS NULL OR end_time > start_time)
);
CREATE INDEX ix_meetings_host_start ON meetings (host_id, start_time);
CREATE INDEX ix_meetings_status_start ON meetings (status, start_time);
CREATE INDEX ix_meetings_org ON meetings (organization_id);
CREATE UNIQUE INDEX ux_meetings_personal_room ON meetings (host_id) WHERE type = 'PERSONAL_ROOM';

CREATE TABLE meeting_rooms (
    id                 uuid PRIMARY KEY,
    meeting_id         uuid        NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
    livekit_room_name  varchar(128) NOT NULL,
    status             varchar(16) NOT NULL,
    started_at         timestamptz NOT NULL,
    ended_at           timestamptz,
    peak_participants  integer     NOT NULL DEFAULT 0,
    version            bigint      NOT NULL DEFAULT 0,
    CONSTRAINT ux_meeting_rooms_name UNIQUE (livekit_room_name),
    CONSTRAINT ck_meeting_rooms_status CHECK (status IN ('ACTIVE', 'ENDED'))
);
-- at most one live session per meeting
CREATE UNIQUE INDEX ux_meeting_rooms_active ON meeting_rooms (meeting_id) WHERE status = 'ACTIVE';
CREATE INDEX ix_meeting_rooms_meeting ON meeting_rooms (meeting_id, started_at DESC);

CREATE TABLE meeting_participants (
    id               uuid PRIMARY KEY,
    meeting_id       uuid         NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
    room_id          uuid REFERENCES meeting_rooms (id) ON DELETE SET NULL,
    user_id          uuid REFERENCES users (id) ON DELETE SET NULL,
    display_name     varchar(120) NOT NULL,
    role             varchar(16)  NOT NULL REFERENCES roles (code),
    state            varchar(16)  NOT NULL,
    wait_token_hash  varchar(64)  NOT NULL,
    ip_address       varchar(64),
    admitted_at      timestamptz,
    joined_at        timestamptz,
    left_at          timestamptz,
    created_at       timestamptz  NOT NULL,
    updated_at       timestamptz  NOT NULL,
    version          bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_participant_role CHECK (role IN ('HOST', 'CO_HOST', 'PARTICIPANT', 'GUEST')),
    CONSTRAINT ck_participant_state CHECK (state IN ('WAITING', 'ADMITTED', 'JOINED', 'LEFT', 'REMOVED', 'DENIED'))
);
CREATE INDEX ix_participants_meeting_state ON meeting_participants (meeting_id, state);
CREATE INDEX ix_participants_room_state ON meeting_participants (room_id, state);
CREATE INDEX ix_participants_user ON meeting_participants (user_id, created_at DESC);

CREATE TABLE meeting_invitations (
    id          uuid PRIMARY KEY,
    meeting_id  uuid         NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
    email       varchar(320) NOT NULL,
    user_id     uuid REFERENCES users (id) ON DELETE SET NULL,
    status      varchar(16)  NOT NULL DEFAULT 'PENDING',
    sent_at     timestamptz,
    created_at  timestamptz  NOT NULL,
    CONSTRAINT ck_invitation_status CHECK (status IN ('PENDING', 'SENT', 'ACCEPTED', 'DECLINED', 'CANCELLED'))
);
CREATE UNIQUE INDEX ux_invitations_meeting_email ON meeting_invitations (meeting_id, lower(email));
CREATE INDEX ix_invitations_user ON meeting_invitations (user_id);
CREATE INDEX ix_invitations_email ON meeting_invitations (lower(email));

-- ---------------------------------------------------------------- scheduling
CREATE TABLE availability_schedules (
    user_id     uuid PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    time_zone   varchar(64) NOT NULL,
    updated_at  timestamptz NOT NULL,
    version     bigint      NOT NULL DEFAULT 0
);

CREATE TABLE availability_rules (
    id           uuid PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    day_of_week  varchar(10) NOT NULL,
    start_time   time        NOT NULL,
    end_time     time        NOT NULL,
    CONSTRAINT ck_rule_window CHECK (end_time > start_time),
    CONSTRAINT ck_rule_day CHECK (day_of_week IN ('MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'))
);
CREATE INDEX ix_availability_rules_user ON availability_rules (user_id);

CREATE TABLE availability_exceptions (
    id              uuid PRIMARY KEY,
    user_id         uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    exception_date  date        NOT NULL,
    available       boolean     NOT NULL,
    start_time      time,
    end_time        time,
    reason          varchar(255),
    created_at      timestamptz NOT NULL,
    CONSTRAINT ck_exception_window CHECK (
        (start_time IS NULL AND end_time IS NULL) OR (start_time IS NOT NULL AND end_time IS NOT NULL AND end_time > start_time)),
    CONSTRAINT ck_exception_available_needs_window CHECK (available = false OR start_time IS NOT NULL)
);
CREATE INDEX ix_availability_exceptions_user_date ON availability_exceptions (user_id, exception_date);

CREATE TABLE booking_pages (
    id                     uuid PRIMARY KEY,
    owner_id               uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    slug                   varchar(60)  NOT NULL,
    title                  varchar(200) NOT NULL,
    description            varchar(5000),
    duration_minutes       integer      NOT NULL,
    slot_interval_minutes  integer      NOT NULL,
    min_notice_minutes     integer      NOT NULL DEFAULT 240,
    max_advance_days       integer      NOT NULL DEFAULT 60,
    buffer_before_minutes  integer      NOT NULL DEFAULT 0,
    buffer_after_minutes   integer      NOT NULL DEFAULT 0,
    media_mode             varchar(16)  NOT NULL DEFAULT 'VIDEO',
    active                 boolean      NOT NULL DEFAULT true,
    created_at             timestamptz  NOT NULL,
    updated_at             timestamptz  NOT NULL,
    version                bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ux_booking_pages_slug UNIQUE (slug),
    CONSTRAINT ck_booking_duration CHECK (duration_minutes BETWEEN 5 AND 480),
    CONSTRAINT ck_booking_interval CHECK (slot_interval_minutes BETWEEN 5 AND 480),
    CONSTRAINT ck_booking_notice CHECK (min_notice_minutes >= 0),
    CONSTRAINT ck_booking_advance CHECK (max_advance_days BETWEEN 1 AND 365),
    CONSTRAINT ck_booking_buffers CHECK (buffer_before_minutes BETWEEN 0 AND 240 AND buffer_after_minutes BETWEEN 0 AND 240)
);
CREATE INDEX ix_booking_pages_owner ON booking_pages (owner_id);

CREATE TABLE bookings (
    id                    uuid PRIMARY KEY,
    booking_page_id       uuid         NOT NULL REFERENCES booking_pages (id) ON DELETE CASCADE,
    host_id               uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    meeting_id            uuid REFERENCES meetings (id) ON DELETE SET NULL,
    status                varchar(16)  NOT NULL,
    start_time            timestamptz  NOT NULL,
    end_time              timestamptz  NOT NULL,
    blocked_start         timestamptz  NOT NULL,
    blocked_end           timestamptz  NOT NULL,
    invitee_name          varchar(120) NOT NULL,
    invitee_email         varchar(320) NOT NULL,
    invitee_time_zone     varchar(64)  NOT NULL,
    notes                 varchar(2000),
    manage_token_hash     varchar(64)  NOT NULL,
    rescheduled_from_id   uuid REFERENCES bookings (id),
    cancelled_at          timestamptz,
    cancel_reason         varchar(500),
    created_at            timestamptz  NOT NULL,
    updated_at            timestamptz  NOT NULL,
    version               bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_bookings_status CHECK (status IN ('CONFIRMED', 'CANCELLED', 'RESCHEDULED')),
    CONSTRAINT ck_bookings_window CHECK (end_time > start_time AND blocked_start <= start_time AND blocked_end >= end_time),
    -- Concurrency-safe double-booking protection: no two confirmed bookings of the same host may overlap,
    -- buffers included. Enforced by PostgreSQL even under concurrent transactions.
    CONSTRAINT ex_bookings_no_overlap EXCLUDE USING gist (
        host_id WITH =,
        tstzrange(blocked_start, blocked_end, '[)') WITH &&
    ) WHERE (status = 'CONFIRMED')
);
CREATE UNIQUE INDEX ux_bookings_manage_token ON bookings (manage_token_hash);
CREATE INDEX ix_bookings_host_start ON bookings (host_id, start_time);
CREATE INDEX ix_bookings_page ON bookings (booking_page_id);

CREATE TABLE calendar_connections (
    id                       uuid PRIMARY KEY,
    user_id                  uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    provider                 varchar(32)  NOT NULL,
    external_account_email   varchar(320),
    access_token_encrypted   text,
    refresh_token_encrypted  text,
    token_expires_at         timestamptz,
    scopes                   varchar(1000),
    status                   varchar(16)  NOT NULL,
    created_at               timestamptz  NOT NULL,
    updated_at               timestamptz  NOT NULL,
    version                  bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_calendar_provider CHECK (provider IN ('GOOGLE', 'MICROSOFT')),
    CONSTRAINT ck_calendar_status CHECK (status IN ('ACTIVE', 'REVOKED', 'ERROR')),
    CONSTRAINT ux_calendar_user_provider UNIQUE (user_id, provider)
);

-- ---------------------------------------------------------------- recordings
CREATE TABLE recordings (
    id                uuid PRIMARY KEY,
    meeting_id        uuid         NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
    room_id           uuid REFERENCES meeting_rooms (id) ON DELETE SET NULL,
    egress_id         varchar(64),
    kind              varchar(16)  NOT NULL DEFAULT 'CLOUD',
    status            varchar(16)  NOT NULL,
    layout            varchar(32),
    audio_only        boolean      NOT NULL DEFAULT false,
    storage_key       varchar(512),
    size_bytes        bigint,
    duration_seconds  bigint,
    started_by        uuid REFERENCES users (id) ON DELETE SET NULL,
    started_at        timestamptz,
    ended_at          timestamptz,
    failure_reason    varchar(1000),
    retention_until   timestamptz,
    deleted_at        timestamptz,
    created_at        timestamptz  NOT NULL,
    updated_at        timestamptz  NOT NULL,
    version           bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_recordings_status CHECK (status IN ('STARTING','ACTIVE','STOPPING','PROCESSING','AVAILABLE','FAILED','DELETED')),
    CONSTRAINT ck_recordings_kind CHECK (kind IN ('CLOUD'))
);
CREATE UNIQUE INDEX ux_recordings_egress ON recordings (egress_id) WHERE egress_id IS NOT NULL;
-- at most one in-flight cloud recording per room session
CREATE UNIQUE INDEX ux_recordings_active_room ON recordings (room_id) WHERE status IN ('STARTING', 'ACTIVE', 'STOPPING');
CREATE INDEX ix_recordings_meeting ON recordings (meeting_id, created_at DESC);
CREATE INDEX ix_recordings_retention ON recordings (retention_until) WHERE status = 'AVAILABLE';

CREATE TABLE recording_access_logs (
    id            uuid PRIMARY KEY,
    recording_id  uuid        NOT NULL REFERENCES recordings (id) ON DELETE CASCADE,
    user_id       uuid REFERENCES users (id) ON DELETE SET NULL,
    access_type   varchar(16) NOT NULL,
    ip_address    varchar(64),
    user_agent    varchar(512),
    created_at    timestamptz NOT NULL,
    CONSTRAINT ck_recording_access_type CHECK (access_type IN ('PLAYBACK', 'DOWNLOAD', 'DELETE'))
);
CREATE INDEX ix_recording_access_recording ON recording_access_logs (recording_id, created_at DESC);

-- ---------------------------------------------------------------- notifications
CREATE TABLE notifications (
    id               uuid PRIMARY KEY,
    user_id          uuid REFERENCES users (id) ON DELETE CASCADE,
    recipient_email  varchar(320),
    channel          varchar(16)  NOT NULL,
    type             varchar(64)  NOT NULL,
    title            varchar(300) NOT NULL,
    body             text,
    link             varchar(1024),
    ics_attachment   text,
    sensitive        boolean      NOT NULL DEFAULT false,
    status           varchar(16)  NOT NULL,
    attempts         integer      NOT NULL DEFAULT 0,
    scheduled_at     timestamptz  NOT NULL,
    sent_at          timestamptz,
    read_at          timestamptz,
    last_error       varchar(1000),
    reference_id     uuid,
    created_at       timestamptz  NOT NULL,
    CONSTRAINT ck_notifications_channel CHECK (channel IN ('IN_APP', 'EMAIL')),
    CONSTRAINT ck_notifications_status CHECK (status IN ('PENDING', 'SENT', 'FAILED', 'CANCELLED')),
    CONSTRAINT ck_notifications_recipient CHECK (user_id IS NOT NULL OR recipient_email IS NOT NULL)
);
CREATE INDEX ix_notifications_dispatch ON notifications (scheduled_at) WHERE status = 'PENDING' AND channel = 'EMAIL';
CREATE INDEX ix_notifications_user ON notifications (user_id, created_at DESC) WHERE channel = 'IN_APP';
CREATE INDEX ix_notifications_reference ON notifications (reference_id);

-- ---------------------------------------------------------------- collaboration
CREATE TABLE chat_messages (
    id              uuid PRIMARY KEY,
    meeting_id      uuid          NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
    room_id         uuid REFERENCES meeting_rooms (id) ON DELETE SET NULL,
    participant_id  uuid          NOT NULL REFERENCES meeting_participants (id) ON DELETE CASCADE,
    sender_name     varchar(120)  NOT NULL,
    text            varchar(4000) NOT NULL,
    created_at      timestamptz   NOT NULL
);
CREATE INDEX ix_chat_meeting_created ON chat_messages (meeting_id, created_at DESC);

CREATE TABLE file_metadata (
    id                           uuid PRIMARY KEY,
    meeting_id                   uuid         NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
    uploaded_by_participant_id   uuid         NOT NULL REFERENCES meeting_participants (id) ON DELETE CASCADE,
    uploaded_by_name             varchar(120) NOT NULL,
    file_name                    varchar(255) NOT NULL,
    content_type                 varchar(127) NOT NULL,
    size_bytes                   bigint       NOT NULL,
    sha256                       varchar(64)  NOT NULL,
    storage_key                  varchar(512) NOT NULL,
    created_at                   timestamptz  NOT NULL,
    deleted_at                   timestamptz
);
CREATE INDEX ix_files_meeting ON file_metadata (meeting_id, created_at DESC);

-- ---------------------------------------------------------------- platform
CREATE TABLE audit_logs (
    id                    uuid PRIMARY KEY,
    actor_user_id         uuid REFERENCES users (id) ON DELETE SET NULL,
    actor_participant_id  uuid,
    action                varchar(64)  NOT NULL,
    resource_type         varchar(32)  NOT NULL,
    resource_id           uuid,
    details               jsonb        NOT NULL DEFAULT '{}'::jsonb,
    ip_address            varchar(64),
    trace_id              varchar(64),
    created_at            timestamptz  NOT NULL
);
CREATE INDEX ix_audit_resource ON audit_logs (resource_type, resource_id, created_at DESC);
CREATE INDEX ix_audit_actor ON audit_logs (actor_user_id, created_at DESC);
CREATE INDEX ix_audit_created ON audit_logs (created_at DESC);
CREATE INDEX ix_audit_action ON audit_logs (action, created_at DESC);

CREATE TABLE webhook_events (
    id            uuid PRIMARY KEY,
    provider      varchar(32)  NOT NULL,
    event_id      varchar(128) NOT NULL,
    event_type    varchar(64)  NOT NULL,
    received_at   timestamptz  NOT NULL,
    processed_at  timestamptz,
    CONSTRAINT ux_webhook_event UNIQUE (provider, event_id)
);

CREATE TABLE idempotency_records (
    id               uuid PRIMARY KEY,
    scope            varchar(64)  NOT NULL,
    idempotency_key  varchar(64)  NOT NULL,
    request_hash     varchar(64)  NOT NULL,
    response_status  integer      NOT NULL,
    response_body    text         NOT NULL,
    created_at       timestamptz  NOT NULL,
    expires_at       timestamptz  NOT NULL,
    CONSTRAINT ux_idempotency UNIQUE (scope, idempotency_key)
);
CREATE INDEX ix_idempotency_expiry ON idempotency_records (expires_at);
